fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, (w / 2) * 8);
        host::display::state_set(2, (h / 3) * 8);
        host::display::state_set(3, 8);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
        host::display::state_set(7, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    let score: i32 = host::display::state_get(5);
    if host::display::state_get(7) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(140, 180, "DROPPED IT", 0xff4040, 3);
        host::display::draw_string(130, 250, "KEEPIES", 0x808080, 2);
        host::display::draw_number(280, 244, score, 0xffffff, 3);
        host::display::draw_string(130, 284, "BEST", 0x808080, 2);
        host::display::draw_number(280, 278, host::display::state_get(6), 0x00ff88, 3);
        host::display::draw_string(140, 350, "TAP TO KICK OFF", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut xf: i32 = host::display::state_get(1);
        let mut yf: i32 = host::display::state_get(2);
        let mut vx: i32 = host::display::state_get(3);
        let mut vy: i32 = host::display::state_get(4);
        vy = vy + 3;
        xf = xf + vx;
        yf = yf + vy;
        let r: i32 = 22;
        if xf < r * 8 { xf = r * 8; vx = -vx * 3 / 4; }
        if xf > (w - r) * 8 { xf = (w - r) * 8; vx = -vx * 3 / 4; }
        if yf < r * 8 { yf = r * 8; vy = -vy; }
        let bx: i32 = xf / 8;
        let by: i32 = yf / 8;
        if tap {
            let dx: i32 = bx - host::display::pointer_x();
            let dy: i32 = by - host::display::pointer_y();
            if dx * dx + dy * dy <= (r + 10) * (r + 10) {
                vy = -34;
                vx = vx + dx * 4;
                if vx > 40 { vx = 40; }
                if vx < -40 { vx = -40; }
                host::display::state_set(5, score + 1);
            }
        }
        if by > h - r {
            host::display::state_set(7, 1);
            if score > host::display::state_get(6) {
                host::display::state_set(6, score);
            }
        }
        host::display::state_set(1, xf);
        host::display::state_set(2, yf);
        host::display::state_set(3, vx);
        host::display::state_set(4, vy);
        host::display::clear(0x0a1414);
        host::display::draw_number(w / 2 - 24, 60, score, 0x1e3a3a, 8);
        host::display::fill_rect(bx - r, by - r, 2 * r, 2 * r, 0xdddddd);
        host::display::fill_rect(bx - r + 6, by - r + 6, 12, 12, 0xffffff);
        host::display::fill_rect(bx - 6, by - 6, 12, 12, 0x222222);
        host::display::draw_string(8, h - 30, "TAP THE BALL TO KEEP IT UP", 0x557777, 2);
    }
    host::display::present();
}
